// A quién toca avisar ahora, y con qué texto exacto.
//
// La ventana NO es "la hora justa". Se avisa de todo lo que esté a menos de las
// horas configuradas y a más de dos, y esto resuelve tres problemas de una vez:
//
//   - Si n8n estuvo parado una hora, el aviso sale en la siguiente pasada en
//     vez de perderse para siempre.
//   - Como la ventana se cierra sola dos horas antes de la cita, un número que
//     Meta rechaza deja de reintentarse solo, sin lista de reintentos.
//   - A quien pide cita para dentro de tres horas no se le manda un
//     recordatorio de algo que acaba de decidir.
//
// Que no se mande dos veces lo garantiza `recordatorio_enviado_at`, que se
// escribe SOLO cuando Meta acepta el mensaje.

const MINIMO_HORAS = 2;
const HORAS_POR_DEFECTO = 24;

/** Lo que sacó un nodo, o nada si no llegó a ejecutarse o vino vacío. */
function deNodo(nombre) {
  try {
    return $(nombre)
      .all()
      .map((i) => i.json)
      .filter((j) => j && j.client_id);
  } catch (e) {
    return [];
  }
}

const citas = deNodo('Citas próximas');
const configs = deNodo('Configuración de agenda');
const credenciales = deNodo('Credenciales de WhatsApp');
const ahora = $now.toMillis();

/** "+34 600 11 22 33" -> "34600112233". Meta quiere dígitos y con país. */
function telefono(valor) {
  let d = String(valor || '').replace(/[^0-9]/g, '');
  if (d.slice(0, 2) === '00') d = d.slice(2);
  // Nueve dígitos es un número español escrito como lo escribe todo el mundo.
  if (d.length === 9) d = '34' + d;
  return d.length >= 11 ? d : '';
}

function enZona(iso, zona, opciones) {
  return new Intl.DateTimeFormat('es-ES', Object.assign({ timeZone: zona }, opciones)).format(
    new Date(iso)
  );
}

/** El día del calendario en la zona del negocio, para comparar días sin líos. */
function diaDe(ms, zona) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: zona }).format(new Date(ms));
}

const avisos = [];

for (const cita of citas) {
  const cfg = configs.find((c) => c.client_id === cita.client_id);

  // Sin activarlo en el panel no se manda nada. El recordatorio le escribe a
  // los clientes de otro negocio: eso se enciende a mano, no por defecto.
  if (!cfg || String(cfg.activo) !== 'true') continue;

  const zona = cfg.zona || 'Europe/Madrid';
  const pedidas = parseInt(cfg.horas || HORAS_POR_DEFECTO, 10) || HORAS_POR_DEFECTO;
  const horas = Math.min(Math.max(pedidas, MINIMO_HORAS + 1), 72);

  const faltan = (new Date(cita.inicio).getTime() - ahora) / 3600000;
  if (faltan > horas || faltan < MINIMO_HORAS) continue;

  const cred = credenciales.find((c) => c.client_id === cita.client_id);
  if (!cred || !cred.token || !cred.phone_number_id) continue;

  const para = telefono(cita.contacto);
  if (!para) continue;

  const negocio = (cita.cliente && cita.cliente.name) || 'tu cita';
  const quien = (cita.trabajador && cita.trabajador.nombre) || 'nosotros';

  let dia = enZona(cita.inicio, zona, { weekday: 'long', day: 'numeric', month: 'long' }).replace(',', '');
  if (diaDe(new Date(cita.inicio).getTime(), zona) === diaDe(ahora + 86400000, zona)) {
    dia = 'mañana ' + dia;
  }

  const hora = enZona(cita.inicio, zona, { hour: '2-digit', minute: '2-digit', hour12: false });

  avisos.push({
    json: {
      cita_id: cita.id,
      client_id: cita.client_id,
      conversation_id: cita.conversation_id || null,
      para,
      phone_number_id: cred.phone_number_id,
      token: cred.token,
      plantilla: cfg.plantilla || 'recordatorio_cita',
      idioma: cfg.idioma || 'es',
      parametros: [negocio, dia, hora, quien],

      // El mismo texto que va a leer la clienta, para dejarlo en la bandeja:
      // quien coja luego esa conversación tiene que ver lo que se le dijo. Si
      // se cambia la plantilla en scripts/plantilla-whatsapp.js, hay que
      // cambiarlo aquí: Meta no devuelve el texto ya montado.
      texto:
        'Recordatorio de tu cita\n\n' +
        'Te recordamos tu cita en ' + negocio + '.\n\n' +
        'Día: ' + dia + '\n' +
        'Hora: ' + hora + '\n' +
        'Con: ' + quien + '\n\n' +
        'Si no puedes venir o quieres cambiarla, contéstanos a este mensaje y lo vemos.',
    },
  });
}

return avisos;

// Meta no lo ha aceptado. No se marca la cita: la próxima pasada lo reintenta,
// y la ventana se cierra sola dos horas antes de la cita, así que un número
// malo no se reintenta eternamente.
const error = $json.error || {};

return {
  json: {
    ok: false,
    cita_id: $('Preparar avisos').item.json.cita_id,
    para: $('Preparar avisos').item.json.para,
    motivo: error.message || 'Meta no ha devuelto un id de mensaje',
    codigo: error.code || null,
  },
};
